const d=window.reportData;const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
function render(){document.title=`${d.meta.title} — ${d.meta.month}`;$('#month').textContent=d.meta.month;$('#hero-title').innerHTML=`${d.meta.title}:<br><span>${d.meta.subtitle}</span>`;$('#hero-sub').textContent='Интерактивный отчёт, который собирает ежедневную событийную повестку в единый образ СибГИУ как научно‑образовательного центра региона.';$('#department').innerHTML=d.department.map((x,i)=>`<article class="card ${x.accent}"><div class="number">0${i+1}</div><h3>${esc(x.title)}</h3><p>${esc(x.text)}</p></article>`).join('');$('#rating').innerHTML=d.rating.map(x=>`<div class="bar-row"><span>${esc(x.label)}</span><div class="track"><div class="fill" style="width:${x.value}%;background:var(--${x.color})"></div></div><b>${x.value}%</b></div>`).join('');$('#priorities').innerHTML=d.priorities.map(x=>`<article class="priority"><b>${x.value}</b><strong>${esc(x.title)}</strong><span>${esc(x.text)}</span></article>`).join('');$('#content').innerHTML=d.content.map(x=>`<article class="day" data-topic="${esc(x.topic)}"><small>${esc(x.date)} · ${esc(x.topic)}</small><h3>${esc(x.title)}</h3><p>${esc(x.text)}</p></article>`).join('');$('#restructuring').innerHTML=d.restructuring.map((x,i)=>`<article class="step"><b>0${i+1} / МОДЕЛЬ</b><h3>${esc(x.title)}</h3><p>${esc(x.text)}</p></article>`).join('')}
function activate(key){document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===key));document.querySelectorAll('[data-panel]').forEach(x=>x.classList.toggle('hidden',x.dataset.panel!==key));window.scrollTo({top:document.querySelector('.tabs').offsetTop-4,behavior:'smooth'})}
render();document.querySelectorAll('.tab').forEach(x=>x.addEventListener('click',()=>activate(x.dataset.tab)));document.querySelectorAll('.filter').forEach(x=>x.addEventListener('click',()=>{document.querySelectorAll('.filter').forEach(b=>b.classList.remove('active'));x.classList.add('active');document.querySelectorAll('.day').forEach(day=>day.style.display=x.dataset.filter==='all'||day.dataset.filter===day.dataset.topic?'block':'none')}));document.querySelectorAll('.navbtn').forEach(x=>x.addEventListener('click',()=>activate(x.dataset.goto)));activate('department');
